import json

name = "skillc"
slug = name.lower().replace(" ", "-").replace("_", "-")

with open('/inputs/devcontainer.json') as f:
    data = json.load(f)

def replace_placeholders(obj):
    if isinstance(obj, dict):
        return {k: replace_placeholders(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [replace_placeholders(v) for v in obj]
    if isinstance(obj, str):
        return obj.replace("{{PROJECT_NAME}}", name).replace("{{PROJECT_SLUG}}", slug)
    return obj

data = replace_placeholders(data)

data["customizations"]["vscode"]["extensions"].extend([
    "ms-python.python",
    "ms-python.vscode-pylance",
    "charliermarsh.ruff"
])

data["customizations"]["vscode"]["settings"]["python.defaultInterpreterPath"] = ".venv/bin/python"
data["customizations"]["vscode"]["settings"]["[python]"] = {
    "editor.defaultFormatter": "charliermarsh.ruff",
    "editor.codeActionsOnSave": {
        "source.organizeImports": "explicit"
    }
}

data["postCreateCommand"] = "rm -rf .venv && uv sync && uv run /opt/post_install.py"

with open('/work/devcontainer.json', 'w') as f:
    json.dump(data, f, indent=2)
    f.write('\n')

print("done")

